@dataclass
class AttachmentRef:
    """
    Reference to one encrypted attachment blob (contains its key: keep it secret).
"""
    def __init__(self, *, key:bytes, sealed_sha256:bytes, plaintext_len:int):
        self.key = key
        self.sealed_sha256 = sealed_sha256
        self.plaintext_len = plaintext_len
        
        

    
    def __str__(self):
        return "AttachmentRef(key={}, sealed_sha256={}, plaintext_len={})".format(self.key, self.sealed_sha256, self.plaintext_len)
    def __eq__(self, other):
        if self.key != other.key:
            return False
        if self.sealed_sha256 != other.sealed_sha256:
            return False
        if self.plaintext_len != other.plaintext_len:
            return False
        return True

