# GroupCryptoError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class GroupCryptoError(Exception):
    """
    Every failure, with a stable machine code (see `docs/group-e2ee.md`).
"""
    pass

_UniffiTempGroupCryptoError = GroupCryptoError

class GroupCryptoError:  # type: ignore
    """
    Every failure, with a stable machine code (see `docs/group-e2ee.md`).
"""
    
    class Failure(_UniffiTempGroupCryptoError):
        """
        Operation failed; `code` is stable, `message` is for logs.
"""
        
        def __init__(self, code, detail):
            super().__init__(", ".join([
                "code={!r}".format(code),
                "detail={!r}".format(detail),
            ]))
            self.code = code
            self.detail = detail

        def __repr__(self):
            return "GroupCryptoError.Failure({})".format(str(self))
    _UniffiTempGroupCryptoError.Failure = Failure # type: ignore

GroupCryptoError = _UniffiTempGroupCryptoError # type: ignore
del _UniffiTempGroupCryptoError


class _UniffiFfiConverterTypeGroupCryptoError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return GroupCryptoError.Failure(
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, GroupCryptoError.Failure):
            _UniffiFfiConverterString.check_lower(value.code)
            _UniffiFfiConverterString.check_lower(value.detail)
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, GroupCryptoError.Failure):
            buf.write_i32(1)
            _UniffiFfiConverterString.write(value.code, buf)
            _UniffiFfiConverterString.write(value.detail, buf)






class Incoming:
    """
    Result of processing one incoming message.
"""
    def __init__(self):
        raise RuntimeError("Incoming cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class MESSAGE:
        
        def __init__(self, message:ReceivedMessage):
            self.message = message
            
            
            pass

    
            
            
    
        def __str__(self):
            return "Incoming.MESSAGE(message={})".format(self.message)
        def __eq__(self, other):
            if not isinstance(other, Incoming):
                return NotImplemented
            if not other.is_MESSAGE():
                return False
            if self.message != other.message:
                return False
            return True

    @dataclass
    class HISTORY_OFFER:
        
        def __init__(self, offer:HistoryOffer):
            self.offer = offer
            
            
            pass

    
            
            
    
        def __str__(self):
            return "Incoming.HISTORY_OFFER(offer={})".format(self.offer)
        def __eq__(self, other):
            if not isinstance(other, Incoming):
                return NotImplemented
            if not other.is_HISTORY_OFFER():
                return False
            if self.offer != other.offer:
                return False
            return True

    @dataclass
    class COMMIT:
        
        def __init__(self, outcome:CommitOutcome):
            self.outcome = outcome
            
            
            pass

    
            
            
    
        def __str__(self):
            return "Incoming.COMMIT(outcome={})".format(self.outcome)
        def __eq__(self, other):
            if not isinstance(other, Incoming):
                return NotImplemented
            if not other.is_COMMIT():
                return False
            if self.outcome != other.outcome:
                return False
            return True

    @dataclass
    class OWN_COMMIT_CONFIRMED:
        
        def __init__(self, outcome:CommitOutcome):
            self.outcome = outcome
            
            
            pass

    
            
            
    
        def __str__(self):
            return "Incoming.OWN_COMMIT_CONFIRMED(outcome={})".format(self.outcome)
        def __eq__(self, other):
            if not isinstance(other, Incoming):
                return NotImplemented
            if not other.is_OWN_COMMIT_CONFIRMED():
                return False
            if self.outcome != other.outcome:
                return False
            return True

    @dataclass
    class OWN:
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "Incoming.OWN()".format()
        def __eq__(self, other):
            if not isinstance(other, Incoming):
                return NotImplemented
            if not other.is_OWN():
                return False
            return True

    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_MESSAGE(self) -> bool:
        return isinstance(self, Incoming.MESSAGE)
    def is_message(self) -> bool:
        return isinstance(self, Incoming.MESSAGE)
    def is_HISTORY_OFFER(self) -> bool:
        return isinstance(self, Incoming.HISTORY_OFFER)
    def is_history_offer(self) -> bool:
        return isinstance(self, Incoming.HISTORY_OFFER)
    def is_COMMIT(self) -> bool:
        return isinstance(self, Incoming.COMMIT)
    def is_commit(self) -> bool:
        return isinstance(self, Incoming.COMMIT)
    def is_OWN_COMMIT_CONFIRMED(self) -> bool:
        return isinstance(self, Incoming.OWN_COMMIT_CONFIRMED)
    def is_own_commit_confirmed(self) -> bool:
        return isinstance(self, Incoming.OWN_COMMIT_CONFIRMED)
    def is_OWN(self) -> bool:
        return isinstance(self, Incoming.OWN)
    def is_own(self) -> bool:
        return isinstance(self, Incoming.OWN)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
Incoming.MESSAGE = type("Incoming.MESSAGE", (Incoming.MESSAGE, Incoming,), {})  # type: ignore
Incoming.HISTORY_OFFER = type("Incoming.HISTORY_OFFER", (Incoming.HISTORY_OFFER, Incoming,), {})  # type: ignore
Incoming.COMMIT = type("Incoming.COMMIT", (Incoming.COMMIT, Incoming,), {})  # type: ignore
Incoming.OWN_COMMIT_CONFIRMED = type("Incoming.OWN_COMMIT_CONFIRMED", (Incoming.OWN_COMMIT_CONFIRMED, Incoming,), {})  # type: ignore
Incoming.OWN = type("Incoming.OWN", (Incoming.OWN, Incoming,), {})  # type: ignore




class _UniffiFfiConverterTypeIncoming(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return Incoming.MESSAGE(
                _UniffiFfiConverterTypeReceivedMessage.read(buf),
            )
        if variant == 2:
            return Incoming.HISTORY_OFFER(
                _UniffiFfiConverterTypeHistoryOffer.read(buf),
            )
        if variant == 3:
            return Incoming.COMMIT(
                _UniffiFfiConverterTypeCommitOutcome.read(buf),
            )
        if variant == 4:
            return Incoming.OWN_COMMIT_CONFIRMED(
                _UniffiFfiConverterTypeCommitOutcome.read(buf),
            )
        if variant == 5:
            return Incoming.OWN(
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_MESSAGE():
            _UniffiFfiConverterTypeReceivedMessage.check_lower(value.message)
            return
        if value.is_HISTORY_OFFER():
            _UniffiFfiConverterTypeHistoryOffer.check_lower(value.offer)
            return
        if value.is_COMMIT():
            _UniffiFfiConverterTypeCommitOutcome.check_lower(value.outcome)
            return
        if value.is_OWN_COMMIT_CONFIRMED():
            _UniffiFfiConverterTypeCommitOutcome.check_lower(value.outcome)
            return
        if value.is_OWN():
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_MESSAGE():
            buf.write_i32(1)
            _UniffiFfiConverterTypeReceivedMessage.write(value.message, buf)
        if value.is_HISTORY_OFFER():
            buf.write_i32(2)
            _UniffiFfiConverterTypeHistoryOffer.write(value.offer, buf)
        if value.is_COMMIT():
            buf.write_i32(3)
            _UniffiFfiConverterTypeCommitOutcome.write(value.outcome, buf)
        if value.is_OWN_COMMIT_CONFIRMED():
            buf.write_i32(4)
            _UniffiFfiConverterTypeCommitOutcome.write(value.outcome, buf)
        if value.is_OWN():
            buf.write_i32(5)



class _UniffiFfiConverterSequenceTypeDeviceRef(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        for item in value:
            _UniffiFfiConverterTypeDeviceRef.check_lower(item)

    @classmethod
    def write(cls, value, buf):
        items = len(value)
        buf.write_i32(items)
        for item in value:
            _UniffiFfiConverterTypeDeviceRef.write(item, buf)

    @classmethod
    def read(cls, buf):
        count = buf.read_i32()
        if count < 0:
            raise InternalError("Unexpected negative sequence length")

        return [
            _UniffiFfiConverterTypeDeviceRef.read(buf) for i in range(count)
        ]

